struct State{original:Option<ToolRunPresentation>,tick:ToolRunTick,end:u32,state:ToolRunState,rate:f32,conflicts:u32,capture:Option<ToolRunPresentation>,source:Option<RetainedCloneSource<ToolRunProgress,ToolRunPresentation>>,clone:Option<ToolRunProgressClone<ToolRunPresentation>>,clone_close:Option<ControlledRetirement<ToolRunProgressClone<ToolRunPresentation>>>,progress:Option<ToolRunProgress>,counter_close:Option<ControlledRetirement<Vec<ToolRunCounter>>>,steps:VecDeque<ToolRunStep>,ring:Option<ToolRunStepRingInsert>,ring_close:Option<ControlledRetirement<ToolRunStepRingInsert>>,provenance_capture:Option<ToolRunEntityProvenance>,provenance:Option<ToolRunEntityProvenanceEdit>,provenance_close:Option<ControlledRetirement<ToolRunEntityProvenanceEdit>>,projected:Option<ToolRunEntityProvenance>,tool_id:Option<SealedShared<String>>,payload:Option<SealedShared<ToolRunPayloadStream>>,payload_update:Option<ToolRunPayloadStreamUpdate>,payload_phase:u8,output:Option<ToolRunPresentation>,step_sequence:u64,phase:u8,cancelled:bool}
pub struct ToolRunPresentationUpdate{state:ManuallyDrop<Box<State>>,transferred:bool}
/// 🎯️ An exclusive original update loan fixes one presentation fragment before funding is checked.
pub struct ToolRunPresentationSelection<'a>{owner:&'a mut ToolRunPresentationUpdate,demand:RetirementDemand}
impl ToolRunPresentationSelection<'_>{
 /// 📏️ Borrows the exact immutable currencies of this original selected fragment.
 pub fn demands(&self)->RetirementDemand{self.demand}
 /// 🎟️ Executes this selected fragment once; independently denied currencies preserve every original child.
 pub fn advance(self,grant:ToolRunEntityEditGrant)->Result<ToolRunEntityEditProgress,ValueError>{if !semio_framework_value::retained_clone::retained_clone_grant_admits(grant.retirement,self.demand){return Ok(Default::default())}if self.owner.next_demands(self.demand.copy_bytes)?!=self.demand{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"selected presentation quote changed under its exact copy frontier"))}self.owner.advance(ToolRunEntityEditGrant{retirement:RetainedCloneGrant{maximum_copy_bytes:self.demand.copy_bytes,maximum_capacity_bytes:self.demand.capacity_bytes,maximum_release_bytes:self.demand.release_bytes,maximum_depth:self.demand.depth,..grant.retirement},..grant})}
}
fn control_demands<T:RetireOwned>(owner:&ControlledRetirement<T>,body:usize)->Result<RetirementDemand,ValueError>{if owner.terminal_is_empty(){return Ok(RetirementDemand{depth:1,..Default::default()});}owner.selected_demand(body)}
impl ToolRunPresentationUpdate{
 pub fn birth_demands()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<State>()+size_of::<ToolRunPresentation>()+size_of::<ToolRunTick>()+size_of::<Self>(),capacity_bytes:size_of::<State>(),depth:1,..Default::default()}}
 pub fn admit(original:ToolRunPresentation,tick:ToolRunTick,end:u32,state:ToolRunState,rate:f32,conflicts:u32,grant:RetainedCloneGrant)->Result<(Self,RetainedCloneProgress),(ValueError,ToolRunPresentation,ToolRunTick)>{let demand=Self::birth_demands();if !semio_framework_value::retained_clone::retained_clone_grant_admits(grant,demand){return Err((ValueError::literal(ValueRefusalKind::OwnershipLimit,"original presentation update birth is not funded"),original,tick));}let step_sequence=original.body().progress.steps.newest().map_or(0,|step|step.sequence);let output=Self{state:ManuallyDrop::new(Box::write(Box::new_uninit(),State{original:Some(original),tick,end,state,rate,conflicts,capture:None,source:None,clone:None,clone_close:None,progress:None,counter_close:None,steps:VecDeque::new(),ring:None,ring_close:None,provenance_capture:None,provenance:None,provenance_close:None,projected:None,tool_id:None,payload:None,payload_update:None,payload_phase:0,output:None,step_sequence,phase:0,cancelled:false})),transferred:false};Ok((output,RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,retained_capacity_bytes:demand.capacity_bytes,..Default::default()}))}
 /// 🧷️ Loans this actual update exclusively until its original selected fragment advances or refuses.
 pub fn select(&mut self,body:usize)->Result<ToolRunPresentationSelection<'_>,ValueError>{let demand=self.next_demands(body)?;Ok(ToolRunPresentationSelection{owner:self,demand})}
 pub fn complete(&self)->bool{self.state.phase==17&&!self.state.cancelled}
 pub fn cancel(&mut self){self.state.cancelled=true;if let Some(child)=self.state.clone.as_mut(){child.cancel();}if let Some(child)=self.state.ring.as_mut(){child.cancel();}if let Some(child)=self.state.provenance.as_mut(){child.cancel();}}
 pub fn edit_capacity_bound(&self)->Result<usize,ValueError>{if let Some(child)=self.state.provenance.as_ref(){return child.edit_capacity_bound();}let count=self.state.original.as_ref().unwrap().body().provenance.marks().len().checked_add(self.state.tick.append_entities.len()).ok_or_else(||ValueError::literal(ValueRefusalKind::OwnershipLimit,"presentation provenance cardinality overflow"))?;ToolRunEntityEdit::<u128>::capacity_bound_for(0,count).ok_or_else(||ValueError::literal(ValueRefusalKind::OwnershipLimit,"presentation provenance capacity overflow"))}
 pub fn next_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{
  let state=&**self.state;if state.cancelled||state.phase>=17{return Ok(Default::default());}let original=state.original.as_ref().unwrap().body();if state.tick.identity.id!=original.progress.identity.id{return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"pending presentation belongs to another original run"));}
  let mut quote=RetirementDemand{depth:1,..Default::default()};match state.phase{
   0=>quote.copy_bytes=ToolRunPresentation::capture_copy_bytes(),
   1=>{quote.copy_bytes=RetainedCloneSource::<ToolRunProgress>::borrowed_constructor_copy_bytes::<ToolRunPresentation>();quote.capacity_bytes=RetainedCloneSource::<ToolRunProgress>::borrowed_constructor_capacity_bytes::<ToolRunPresentation>();},
   2=>quote.copy_bytes=size_of::<RetainedCloneSource<ToolRunProgress,ToolRunPresentation>>(),
   3=>{let child=state.clone.as_ref().unwrap();quote=if child.complete(){RetirementDemand{copy_bytes:size_of::<ToolRunProgress>()+size_of::<ToolRunProgressClone<ToolRunPresentation>>(),depth:1,..Default::default()}}else{child.next_demands()?};},
   4=>quote=control_demands(state.clone_close.as_ref().unwrap(),body)?,
   5=>quote.copy_bytes=size_of::<ToolRunProgress>()+2*size_of::<Vec<ToolRunCounter>>(),
   6=>if let Some(child)=state.counter_close.as_ref(){quote=control_demands(child,body)?;},
   7=>quote.copy_bytes=size_of::<Vec<ToolRunStep>>()+size_of::<VecDeque<ToolRunStep>>(),
   8=>if let Some(child)=state.ring.as_ref(){quote=if child.complete(){RetirementDemand{copy_bytes:size_of::<ToolRunStepRing>()+size_of::<ToolRunStepRingInsert>(),depth:1,..Default::default()}}else{child.next_demands()?.retirement};}else if !state.steps.is_empty(){quote.copy_bytes=size_of::<ToolRunStepRing>()+size_of::<ToolRunStep>();},
   9=>quote=control_demands(state.ring_close.as_ref().unwrap(),body)?,
   10=>quote.copy_bytes=ToolRunEntityProvenance::capture_copy_bytes(),
   11=>quote.copy_bytes=size_of::<ToolRunEntityProvenance>()+size_of::<Vec<u64>>()+size_of::<Option<u32>>()+size_of::<u32>(),
   12=>{let child=state.provenance.as_ref().unwrap();quote=if child.complete(){let mut quote=child.publication_demands();quote.copy_bytes+=size_of::<ToolRunEntityProvenanceEdit>();quote}else{child.next_demands(body)?};},
   13=>quote=control_demands(state.provenance_close.as_ref().unwrap(),body)?,
   14=>quote.copy_bytes=size_of::<SealedShared<String>>(),
   15=>{quote=match state.payload_phase{
    0=>RetirementDemand{copy_bytes:size_of::<Option<SealedShared<ToolRunPayloadStream>>>(),depth:1,..Default::default()},
    1=>{let mut demand=ToolRunPayloadStreamUpdate::birth_demand();demand.copy_bytes+=size_of::<Option<ToolRunPayloadStreamUpdate>>();demand},
    2=>{let child=state.payload_update.as_ref().unwrap();if child.complete(){child.take_demand()}else{child.demand()?}},
    3=>{let child=state.payload_update.as_ref().unwrap();if child.terminal_is_empty(){RetirementDemand{copy_bytes:size_of::<Option<ToolRunPayloadStreamUpdate>>(),depth:1,..Default::default()}}else{child.close_demand(body)?}},
    _=>return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"presentation payload phase is invalid")),
   };},
   16=>quote=ToolRunPresentation::birth_demands(),
   _=>return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"pending presentation phase is invalid")),
  }Ok(quote)
 }
 pub fn advance(&mut self,grant:ToolRunEntityEditGrant)->Result<ToolRunEntityEditProgress,ValueError>{
  if self.state.cancelled||self.state.phase>=17||grant.retirement.maximum_items==0{return Ok(Default::default());}let quote=self.next_demands(grant.retirement.maximum_copy_bytes)?;if quote.copy_bytes>grant.retirement.maximum_copy_bytes||quote.capacity_bytes>grant.retirement.maximum_capacity_bytes||quote.release_bytes>grant.retirement.maximum_release_bytes||quote.depth>grant.retirement.maximum_depth{return Ok(Default::default());}
  let state=&mut**self.state;let mut receipt=ToolRunEntityEditProgress{retirement:RetainedCloneProgress{copied_items:1,copied_bytes:quote.copy_bytes,..Default::default()},..Default::default()};match state.phase{
   0=>{let(capture,progress)=state.original.as_ref().unwrap().capture(grant.retirement)?;state.capture=Some(capture);receipt.retirement=progress;state.phase=1;},
   1=>{let original=state.capture.take().unwrap();match RetainedCloneSource::admit_borrowed(original,|original|&original.body().progress,grant.retirement){Ok((source,progress))=>{state.source=Some(source);receipt.retirement=progress;state.phase=2;},Err((error,original))=>{state.capture=Some(original);return Err(error);}}},
   2=>{state.clone=Some(ToolRunProgressClone::new(state.source.take().unwrap()));state.phase=3;},
   3=>{let child=state.clone.as_mut().unwrap();if !child.complete(){return child.advance(grant.retirement).map(|retirement|ToolRunEntityEditProgress{retirement,..Default::default()});}state.progress=Some(child.take_output(grant.retirement)?.unwrap().0);let child=state.clone.take().unwrap();match ControlledRetirement::new(child){Ok(close)=>state.clone_close=Some(close),Err((error,child))=>{state.clone=Some(child);return Err(error);}}state.phase=4;},
   4=>{let child=state.clone_close.as_mut().unwrap();if !child.terminal_is_empty(){return child.step(grant.retirement).map(|step|ToolRunEntityEditProgress{retirement:step.progress(),..Default::default()});}state.clone_close=None;state.phase=5;},
   5=>{let progress=state.progress.as_mut().unwrap();progress.identity=state.tick.identity;progress.sequence=progress.sequence.max(state.tick.sequence);progress.state=state.state;progress.units_per_second=state.rate;progress.conflicts=state.conflicts;if let Some(update)=state.tick.progress.as_mut(){progress.stage=update.stage;progress.total=update.total;progress.completed=update.total.map_or(update.completed,|total|update.completed.min(total));let counters=std::mem::replace(&mut progress.counters,std::mem::take(&mut update.counters));match ControlledRetirement::new(counters){Ok(close)=>state.counter_close=Some(close),Err((error,counters))=>{update.counters=std::mem::replace(&mut progress.counters,counters);return Err(error);}}}state.phase=6;},
   6=>{if let Some(child)=state.counter_close.as_mut(){if !child.terminal_is_empty(){return child.step(grant.retirement).map(|step|ToolRunEntityEditProgress{retirement:step.progress(),..Default::default()});}state.counter_close=None;}state.phase=7;},
   7=>{state.steps=std::mem::take(&mut state.tick.steps).into();state.phase=8;},
   8=>{if let Some(child)=state.ring.as_mut(){if !child.complete(){let step=child.advance(ToolRunStepRingInsertGrant{retirement:grant.retirement,comparison:grant.comparison,maximum_moved_items:grant.maximum_moved_items,maximum_moved_bytes:grant.maximum_moved_bytes})?;return Ok(ToolRunEntityEditProgress{retirement:step.retirement,comparison:step.comparison,moved_items:step.moved_items,moved_bytes:step.moved_bytes,..Default::default()});}state.progress.as_mut().unwrap().steps=child.take_output(grant.retirement)?.unwrap().0;let child=state.ring.take().unwrap();match ControlledRetirement::new(child){Ok(close)=>state.ring_close=Some(close),Err((error,child))=>{state.ring=Some(child);return Err(error);}}state.phase=9;}else if let Some(mut step)=state.steps.pop_front(){state.step_sequence=state.step_sequence.saturating_add(1);step.sequence=state.step_sequence;let ring=std::mem::take(&mut state.progress.as_mut().unwrap().steps);state.ring=Some(ToolRunStepRingInsert::new(ring,step));}else{state.phase=10;}},
   9=>{let child=state.ring_close.as_mut().unwrap();if !child.terminal_is_empty(){return child.step(grant.retirement).map(|step|ToolRunEntityEditProgress{retirement:step.progress(),..Default::default()});}state.ring_close=None;state.phase=8;},
   10=>{let(capture,progress)=state.original.as_ref().unwrap().body().provenance.capture(grant.retirement)?;state.provenance_capture=Some(capture);receipt.retirement=progress;state.phase=11;},
   11=>{state.provenance=Some(ToolRunEntityProvenanceEdit::new(state.provenance_capture.take().unwrap(),state.tick.retract_to,state.end,std::mem::take(&mut state.tick.append_entities)));state.phase=12;},
   12=>{let child=state.provenance.as_mut().unwrap();if !child.complete(){return child.advance(grant);}let(projected,progress)=child.take_output(grant.retirement)?.unwrap();state.projected=Some(projected);receipt.retirement=RetainedCloneProgress{copied_bytes:quote.copy_bytes,..progress};let child=state.provenance.take().unwrap();match ControlledRetirement::new(child){Ok(close)=>state.provenance_close=Some(close),Err((error,child))=>{state.provenance=Some(child);return Err(error);}}state.phase=13;},
   13=>{let child=state.provenance_close.as_mut().unwrap();if !child.terminal_is_empty(){return child.step(grant.retirement).map(|step|ToolRunEntityEditProgress{retirement:step.progress(),..Default::default()});}state.provenance_close=None;state.phase=14;},
   14=>{let(tool_id,progress)=state.original.as_ref().unwrap().body().tool_id.try_duplicate(grant.retirement)?;state.tool_id=Some(tool_id);receipt.retirement=progress;state.phase=15;},
   15=>{match state.payload_phase{
    0=>{if let Some(payload)=state.original.as_ref().unwrap().body().payload.as_ref(){let(payload,mut progress)=payload.try_duplicate(grant.retirement)?;progress.copied_bytes=quote.copy_bytes;state.payload=Some(payload);receipt.retirement=progress;}if state.tick.payload.is_some(){state.payload_phase=1;}else{state.phase=16;}},
    1=>{let mut update=ToolRunPayloadStreamUpdate::empty();let progress=update.admit(&mut state.payload,&mut state.tick.payload,state.tick.identity,state.tick.payload_update.unwrap_or(ToolRunPayloadUpdate::Replace),grant.retirement)?.ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"funded original payload admission refused"))?;state.payload_update=Some(update);receipt.retirement=RetainedCloneProgress{copied_bytes:quote.copy_bytes,..progress};state.payload_phase=2;},
    2=>{let child=state.payload_update.as_mut().unwrap();if child.complete(){let(payload,progress)=child.take(grant.retirement)?.unwrap();state.payload=Some(payload);child.begin_close();state.payload_phase=3;receipt.retirement=progress;}else{receipt.retirement=child.advance(grant.retirement)?.progress();}},
    3=>{let child=state.payload_update.as_mut().unwrap();if child.terminal_is_empty(){state.payload_update=None;state.phase=16;}else{receipt.retirement=child.close_step(grant.retirement)?.progress();}},
    _=>unreachable!(),
   }},
   16=>{let body=ToolRunPresentationBody{tool_id:state.tool_id.take().unwrap(),progress:state.progress.take().unwrap(),provenance:state.projected.take().unwrap(),payload:state.payload.take()};match ToolRunPresentation::admit(body,grant.retirement){Ok((output,progress))=>{state.output=Some(output);receipt.retirement=progress;state.phase=17;},Err((error,body))=>{state.tool_id=Some(body.tool_id);state.progress=Some(body.progress);state.projected=Some(body.provenance);state.payload=body.payload;return Err(error);}}},
   _=>unreachable!(),
  }Ok(receipt)
 }
 pub fn take_output(&mut self,grant:RetainedCloneGrant)->Result<Option<(ToolRunPresentation,RetainedCloneProgress)>,ValueError>{if !self.complete()||grant.maximum_items==0||grant.maximum_copy_bytes<size_of::<ToolRunPresentation>()||grant.maximum_depth==0{return Ok(None);}state_take_output(&mut self.state,grant)}
}
fn state_take_output(state:&mut State,_grant:RetainedCloneGrant)->Result<Option<(ToolRunPresentation,RetainedCloneProgress)>,ValueError>{let output=state.output.take().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"completed presentation lost its unpublished output"))?;state.phase=18;Ok(Some((output,RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<ToolRunPresentation>(),..Default::default()})))}
impl RetireOwned for ToolRunPresentationUpdate{fn retirement(mut self)->Box<dyn RetirementCursor>{self.transferred=true;unsafe{ManuallyDrop::take(&mut self.state)}.retirement()}fn retirement_birth_bytes(&self)->Option<usize>{RetireOwned::retirement_birth_bytes(&*self.state)}fn controlled_retirement_supported()->bool{true}fn retirement_element_copy_bytes()->usize{size_of::<Self>()}}
impl Drop for ToolRunPresentationUpdate{fn drop(&mut self){if !self.transferred&&!std::thread::panicking(){panic!("pending original presentation requires controlled retirement")}}}
